// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value) internal {
        vm.assume(true);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool withdrewReverted;
        try c.withdraw(_value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue((withdrewReverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            ||
            (!withdrewReverted && afterDeposits == beforeDeposits && afterBalance <= beforeBalance));
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable { }
}
